 reach you.</p>⏎<p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#374151;">To get it delivered, {% if shop.phone %}call us at {{ shop.phone }} or {% endif %}reply to this email.</p>⏎</td></tr>⏎{% if shipment.tracking_url or order.status_url %}<tr><td style="padding:12px 32px 4px;">⏎<a href="{{ shipment.tracking_url | default: order.status_url }}" style="display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;">Track your parcel</a>⏎</td></tr>{% endif %}⏎⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), '2026-10-30T04:42:55.459Z', '2026-10-30T04:42:55.459Z', 'Courier could not reach', '[]', '00000000-0000-4000-8000-000000000001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0);
