p>⏎</td></tr>⏎{% if shop.review_url %}<tr><td style="padding:12px 32px 4px;">⏎<a href="{{ shop.review_url }}" style="display:inline-block;background:{{ accent }};color:#ffffff;text-decoration:none;font-size:15px;font-weight:600;padding:12px 22px;border-radius:8px;">Write a review</a>⏎</td></tr>{% endif %}⏎<tr><td style="padding:8px 32px 0;">⏎<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid #e5e7eb;">⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">Order</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.name }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">Items</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.item_count }}</td></tr>⏎<tr><td style="padding:6px 0;font-size:14px;color:#374151;">Total</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.total_price | money }}</td></tr>⏎{% if order.cod_amount > 0 %}<tr><td style="padding:6px 0;font-size:14px;color:#374151;">To pay on delivery</td><td align="right" style="padding:6px 0;font-size:14px;color:#374151;">{{ order.cod_amount | money }}</td></tr>{% endif %}⏎</table>⏎</td></tr>⏎<tr><td style="padding:28px 32px 28px;">⏎<p style="margin:0;padding-top:20px;border-top:1px solid #e5e7eb;font-size:13px;line-height:1.6;color:#6b7280;">{{ shop.name }}{% if shop.phone %} · {{ shop.phone }}{% endif %}{% if shop.email %} · {{ shop.email }}{% endif %}{% if shop.address %}<br>{{ shop.address }}{% endif %}</p>⏎</td></tr>⏎</table>⏎</td></tr>⏎</table>⏎</body>⏎</html>', '⏎', char(10)), '2026-10-30T04:42:55.459Z', '2026-10-30T04:42:55.459Z', 'Review request', '[]', '00000000-0000-4000-8000-000000000001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0);
