INSERT INTO "platform_automation_rules" ("id", "name", "description", "trigger", "conditions", "actions", "enabled", "cooldown_minutes", "max_actions_per_run", "archived_at", "last_run_at", "last_result", "created_by", "created_at", "updated_by", "updated_at") VALUES ('20a86431-91e5-4862-88f5-17ebe75772ba', 'Escalate overdue tickets', 'Raise an overdue ticket one step and tell the support managers.', 'ticket_overdue', '{"max_level":3}', '[{"type":"escalate_ticket"}]', 1, 240, 25, NULL, NULL, NULL, NULL, '2026-10-30T04:42:54.749Z', NULL, '2026-10-30T04:42:54.749Z');
INSERT INTO "platform_automation_rules" ("id", "name", "description", "trigger", "conditions", "actions", "enabled", "cooldown_minutes", "max_actions_per_run", "archived_at", "last_run_at", "last_result", "created_by", "created_at", "updated_by", "updated_at") VALUES ('8a62a6cd-d7b3-4713-a191-aba2a9847d6e', 'Repeated integration failures → technical support', 'Tell technical support when a merchant''s integrations keep failing.', 'integration_failures', '{"hours":24,"min_errors":5}', '[{"type":"notify_staff","action":"edit","module":"integrations","severity":"WARN"},{"type":"notify_account_manager"}]', 1, 1440, 25, NULL, NULL, NULL, NULL, '2026-10-30T04:42:54.749Z', NULL, '2026-10-30T04:42:54.749Z');
