INSERT INTO "platform_automation_rules" ("id", "name", "description", "trigger", "conditions", "actions", "enabled", "cooldown_minutes", "max_actions_per_run", "archived_at", "last_run_at", "last_result", "created_by", "created_at", "updated_by", "updated_at") VALUES ('b6e25b06-7279-4899-b84b-503d716f1268', 'Usage limit reached', 'Tell the merchant (in-app) and their account manager when SMS or BD Courier requests are refused.', 'usage_limit', '{"hours":24,"min_refused":1}', '[{"body":"Some SMS or courier history checks could not run because a limit or your credits ran out. Recharge or check your plan under Plan & Billing.","kind":"USAGE","link":"/admin/settings/billing","type":"notify_merchant","title":"A usage limit was reached","severity":"WARN"},{"type":"notify_account_manager","severity":"INFO"}]', 0, 1440, 25, NULL, NULL, NULL, NULL, '2026-10-30T04:42:54.749Z', NULL, '2026-10-30T04:42:54.749Z');
