INSERT INTO "platform_automation_rules" ("id", "name", "description", "trigger", "conditions", "actions", "enabled", "cooldown_minutes", "max_actions_per_run", "archived_at", "last_run_at", "last_result", "created_by", "created_at", "updated_by", "updated_at") VALUES ('71eaf0bb-1803-4c29-a4ca-19c85d30a1a4', 'Platform service down → incident', 'Open an incident when the platform SMS, BD Courier or PBX gateway stops working.', 'service_down', '{"minutes":10}', '[{"type":"create_incident","severity":"HIGH"},{"type":"notify_staff","action":"manage","module":"health","severity":"CRITICAL"}]', 1, 60, 25, NULL, NULL, NULL, NULL, '2026-10-30T04:42:54.749Z', NULL, '2026-10-30T04:42:54.749Z');
